// @vitest-environment jsdom
import * as React from 'react';
import { act } from 'react';
import { createRoot } from 'react-dom/client';
import { describe, it, expect, beforeEach } from 'vitest';
import { ThemeProvider } from '@gravity-ui/uikit';
import { App } from './App';

(globalThis as any).IS_REACT_ACT_ENVIRONMENT = true;
(globalThis as any).ResizeObserver = class { observe() {} unobserve() {} disconnect() {} };
(globalThis as any).matchMedia ??= () => ({ matches: false, addListener() {}, removeListener() {}, addEventListener() {}, removeEventListener() {} });

let container: HTMLDivElement;
const q = <E extends Element = HTMLElement>(sel: string) => container.querySelector<E>(sel)!;
const qa = (sel: string) => Array.from(container.querySelectorAll<HTMLElement>(sel));
const bodyRows = () => qa('tbody tr');
const col = (i: number) => bodyRows().map((tr) => tr.querySelectorAll('td')[i].textContent!.trim());
const selectedLabel = () => container.textContent!.match(/Выбрано строк: (\d+)/)![1];
const headerCheckbox = () => q<HTMLInputElement>('thead input[type="checkbox"]');
const rowCheckboxes = () => qa('tbody input[type="checkbox"]') as unknown as HTMLInputElement[];
const pageButton = (label: string) => qa('button').find((b) => b.textContent === label && !b.closest('[data-qa="pagination-page-sizer"]'))!;
const headerByText = (t: string) => qa('thead [role="button"]').find((h) => h.textContent!.includes(t))!;

function click(el: Element) {
  act(() => {
    (el as HTMLElement).dispatchEvent(new MouseEvent('click', { bubbles: true }));
  });
}

beforeEach(() => {
  container = document.createElement('div');
  document.body.appendChild(container);
  const root = createRoot(container);
  act(() => {
    root.render(
      <ThemeProvider theme="light">
        <App />
      </ThemeProvider>,
    );
  });
});

describe('DataTable', () => {
  it('renders 10 rows and 9 pages for 87 items', () => {
    expect(bodyRows().length).toBe(10);
    expect(selectedLabel()).toBe('0');
    expect(pageButton('9')).toBeTruthy();
    expect(qa('button').some((b) => b.textContent === '10' && !b.closest('[data-qa="pagination-page-sizer"]'))).toBe(false);
  });

  it('sorts by column asc -> desc -> none across the whole dataset', () => {
    const nameHeader = headerByText('Сотрудник');
    click(nameHeader);
    const asc = col(1);
    expect(asc).toEqual([...asc].sort((a, b) => a.localeCompare(b, 'ru')));
    click(nameHeader);
    const desc = col(1);
    expect(desc).toEqual([...desc].sort((a, b) => b.localeCompare(a, 'ru')));
    click(nameHeader);
    expect(col(1)).not.toEqual(asc); // back to original order
  });

  it('sorts numeric salary column numerically', () => {
    const h = headerByText('Зарплата');
    click(h);
    const salaries = bodyRows().map((tr) => Number(tr.querySelectorAll('td')[4].textContent!.replace(/\D/g, '')));
    expect(salaries).toEqual([...salaries].sort((a, b) => a - b));
    click(h);
    const desc = bodyRows().map((tr) => Number(tr.querySelectorAll('td')[4].textContent!.replace(/\D/g, '')));
    expect(desc).toEqual([...desc].sort((a, b) => b - a));
  });

  it('keeps sort order when paging, and selection survives paging', () => {
    const h = headerByText('Зарплата');
    click(h);
    click(h); // desc
    const firstPageSalaries = bodyRows().map((tr) => Number(tr.querySelectorAll('td')[4].textContent!.replace(/\D/g, '')));
    click(rowCheckboxes()[0]);
    click(rowCheckboxes()[1]);
    expect(selectedLabel()).toBe('2');

    click(pageButton('2'));
    expect(bodyRows().length).toBe(10);
    const secondPage = bodyRows().map((tr) => Number(tr.querySelectorAll('td')[4].textContent!.replace(/\D/g, '')));
    // page 2 continues the desc order from page 1 (global sort, not per-page)
    expect(Math.min(...firstPageSalaries)).toBeGreaterThanOrEqual(Math.max(...secondPage));
    expect(selectedLabel()).toBe('2');
    // header checkbox on page 2 is unchecked (no row on this page selected)
    expect(headerCheckbox().checked).toBe(false);

    click(pageButton('9'));
    expect(bodyRows().length).toBe(7);
    expect(selectedLabel()).toBe('2');
  });

  it('header checkbox selects / clears the current page only', () => {
    click(headerCheckbox());
    expect(selectedLabel()).toBe('10');
    expect(rowCheckboxes().every((c) => c.checked)).toBe(true);
    click(headerCheckbox());
    expect(selectedLabel()).toBe('0');
  });

  it('clear selection button resets all selection', () => {
    click(rowCheckboxes()[0]);
    click(rowCheckboxes()[3]);
    expect(selectedLabel()).toBe('2');
    click(qa('button').find((b) => b.textContent?.includes('Сбросить выбор'))!);
    expect(selectedLabel()).toBe('0');
    expect(rowCheckboxes().some((c) => c.checked)).toBe(false);
  });
});
EOF
